import{_ as a,o as l,c as i,O as t}from"./chunks/framework.db831a78.js";const m=JSON.parse('{"title":"工具 & 运维","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/10-工具运维.md","filePath":"interview/后端/Java/10-工具运维.md","lastUpdated":null}'),r={name:"interview/后端/Java/10-工具运维.md"};function o(n,e,s,d,c,u){return l(),i("div",null,e[0]||(e[0]=[t('<h1 id="工具-运维" tabindex="-1">工具 &amp; 运维 <a class="header-anchor" href="#工具-运维" aria-label="Permalink to &quot;工具 &amp; 运维&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="git-常用命令-merge-与-rebase-★★☆" tabindex="-1">Git 常用命令；merge 与 rebase ★★☆ <a class="header-anchor" href="#git-常用命令-merge-与-rebase-★★☆" aria-label="Permalink to &quot;Git 常用命令；merge 与 rebase ★★☆&quot;">​</a></h2><ul><li>常用：add、commit、push、pull、branch、checkout/switch、merge、rebase、stash、log、reset、tag。</li><li>merge：保留两条线，生成合并提交，历史真实但分叉多；rebase：把提交变基到目标分支顶部，历史线性干净，但改写历史（公共分支慎用）。</li></ul><h2 id="maven-依赖冲突-★★☆" tabindex="-1">Maven 依赖冲突 ★★☆ <a class="header-anchor" href="#maven-依赖冲突-★★☆" aria-label="Permalink to &quot;Maven 依赖冲突 ★★☆&quot;">​</a></h2><ul><li>原因：传递依赖版本不一致；用 <code>mvn dependency:tree</code> 查看。</li><li>解决：最短路径优先/最先声明优先、<code>&lt;exclusions&gt;</code> 排除、<code>dependencyManagement</code> 统一版本、升级/对齐版本。</li></ul><h2 id="docker-基础概念-镜像、容器-★★☆" tabindex="-1">Docker 基础概念；镜像、容器 ★★☆ <a class="header-anchor" href="#docker-基础概念-镜像、容器-★★☆" aria-label="Permalink to &quot;Docker 基础概念；镜像、容器 ★★☆&quot;">​</a></h2><ul><li>镜像 Image：只读模板（分层）；容器 Container：镜像运行实例（可读写层）；Dockerfile 构建、仓库（Registry）存储分发。</li><li>常用：build、run、exec、ps、images、logs、compose；数据卷 volume 持久化、端口映射 -p。</li></ul><h2 id="linux-常用命令-进程、日志、端口、内存-cpu-★★★" tabindex="-1">Linux 常用命令：进程、日志、端口、内存 CPU ★★★ <a class="header-anchor" href="#linux-常用命令-进程、日志、端口、内存-cpu-★★★" aria-label="Permalink to &quot;Linux 常用命令：进程、日志、端口、内存 CPU ★★★&quot;">​</a></h2><ul><li>进程：ps、top、kill；日志：tail -f、less、grep；端口：netstat -tlnp、ss、lsof -i:port；内存/CPU：free、top、vmstat。</li><li>磁盘：df、du；性能：iostat、sar。</li></ul><h2 id="xss、csrf、密码加密-★★★" tabindex="-1">XSS、CSRF、密码加密 ★★★ <a class="header-anchor" href="#xss、csrf、密码加密-★★★" aria-label="Permalink to &quot;XSS、CSRF、密码加密 ★★★&quot;">​</a></h2><ul><li>XSS 跨站脚本：存储型/反射型/DOM 型，注入脚本；防御：输入过滤、输出转义、CSP、HttpOnly Cookie。</li><li>CSRF 跨站请求伪造：诱导已登录用户发请求；防御：CSRF Token、同源检测（Referer/Origin）、SameSite Cookie。</li><li>密码加密：哈希加盐（如 BCrypt/Argon2，慢哈希防暴力），不可逆，避免明文与可逆加密。</li></ul><h2 id="sql-注入、越权-★★★" tabindex="-1">SQL 注入、越权 ★★★ <a class="header-anchor" href="#sql-注入、越权-★★★" aria-label="Permalink to &quot;SQL 注入、越权 ★★★&quot;">​</a></h2><ul><li>SQL 注入：拼接 SQL 导致注入；防御：预编译参数化（MyBatis #{}）、最小权限、WAF。</li><li>越权：水平（访问他人同权限数据）与垂直（低权限访问高权限）；防御：服务端鉴权、资源归属校验、接口级权限控制。</li></ul><h2 id="线上排查完整流程、线程-dump-分析-★★★" tabindex="-1">线上排查完整流程、线程 dump 分析 ★★★ <a class="header-anchor" href="#线上排查完整流程、线程-dump-分析-★★★" aria-label="Permalink to &quot;线上排查完整流程、线程 dump 分析 ★★★&quot;">​</a></h2><ul><li>流程：明确现象 → 看监控告警/日志 → 定位服务与耗时环节 → 针对性查 DB 慢查询/线程栈/GC/依赖 → 修复并回归 → 沉淀复盘。</li><li>线程 dump：jstack、jcmd Thread.print，分析 BLOCKED（锁等待）、WAITING、死锁、空闲线程过多；多抓几次对比。</li></ul><h2 id="jvm-调优参数、日志框架、监控体系-★★☆" tabindex="-1">JVM 调优参数、日志框架、监控体系 ★★☆ <a class="header-anchor" href="#jvm-调优参数、日志框架、监控体系-★★☆" aria-label="Permalink to &quot;JVM 调优参数、日志框架、监控体系 ★★☆&quot;">​</a></h2><ul><li>JVM 调优：先量后调（看 GC 日志），堆大小、GC 选择（G1）、并行线程数，避免盲目加内存。</li><li>日志框架：SLF4J 门面 + Logback/Log4j2 实现；异步日志、滚动策略、日志脱敏、traceId 关联。</li><li>监控：指标 Prometheus + Grafana，链路 SkyWalking/Zipkin，日志 ELK；加告警阈值，早发现早处理。</li></ul>',18)]))}const p=a(r,[["render",o]]);export{m as __pageData,p as default};
